select v.id, upper(regexp_replace(coalesce(v.header->>'kennzeichen',''),'[^A-Za-z0-9]','','g')) plate, v.statut, v.deleted_at is not null deleted, s.name station, v.header->>'leistungsdatum' datum, v.created_at::date created from vehicles v left join stations s on s.id=v.station_id where upper(regexp_replace(coalesce(v.header->>'kennzeichen',''),'[^A-Za-z0-9]','','g')) in ('0745JVM','2187FNS','6555JBL','5420HZC','2081HGC','1188JYM','2709MXN','9663MYF','9547LPV','3861KJZ','7644MTF','9133HHT','6261KCK','7216KJW','6537KZZ','2207GTP','7922KRV','4389FXN','4482FDH','1640HFN','3880LJB','1704MFM','0796FLV','2141MZL','4269NLH','6550JZB','9429JSJ') order by plate;
select count(*) total_live from vehicles where deleted_at is null;
